// Pattern: malware polls several LLM providers for a vote on its next action,
// then reports and exfiltrates over a Discord webhook.
// Keep AiProviderDomains and BrowserProcesses current.
let Lookback = 7d;
let CorrelationWindow = 15m;
let AiProviderDomains = dynamic([
    "api.deepseek.com",
    "dashscope.aliyuncs.com",
    "api.mistral.ai",
    "generativelanguage.googleapis.com"
]);
let DiscordDomains = dynamic(["discord.com", "discordapp.com", "cdn.discordapp.com"]);
let BrowserProcesses = dynamic(["chrome.exe", "msedge.exe", "firefox.exe", "brave.exe", "opera.exe"]);
let AiCalls = DeviceNetworkEvents
| where Timestamp > ago(Lookback)
| where ActionType == "ConnectionSuccess"
| where RemoteUrl in~ (AiProviderDomains)
| where InitiatingProcessFileName !in~ (BrowserProcesses)
| summarize AiProviders = make_set(RemoteUrl), AiCallCount = count(), FirstAiCall = min(Timestamp), LastAiCall = max(Timestamp)
    by DeviceId, DeviceName, InitiatingProcessFileName, InitiatingProcessId
| where array_length(AiProviders) >= 2;
let DiscordCalls = DeviceNetworkEvents
| where Timestamp > ago(Lookback)
| where ActionType == "ConnectionSuccess"
| where RemoteUrl has_any (DiscordDomains)
| where InitiatingProcessFileName !in~ (BrowserProcesses)
| project DeviceId, InitiatingProcessId, DiscordTime = Timestamp, DiscordUrl = RemoteUrl;
AiCalls
| join kind=inner DiscordCalls on DeviceId, InitiatingProcessId
| where DiscordTime between (FirstAiCall .. LastAiCall + CorrelationWindow)
| project DeviceName, InitiatingProcessFileName, AiProviders, AiCallCount, FirstAiCall, LastAiCall, DiscordTime, DiscordUrl
| order by LastAiCall desc

// Guests with no recent successful sign-in, privileged and most dormant first. Hunting query, not an alert.
// Lookback must not exceed the retention of both sign-in tables.
let Lookback = 90d;
let MinSilentDays = 30;
let IdentityLookback = 14d;
let Guests = IdentityInfo
    | where TimeGenerated > ago(IdentityLookback)
    | extend Upn = tolower(coalesce(column_ifexists("AccountUPN", ""), column_ifexists("AccountUpn", "")))
    | extend MemberType = coalesce(column_ifexists("UserType", ""), column_ifexists("TenantMembershipType", ""))
    | where MemberType =~ "Guest" and isnotempty(Upn)
    | summarize arg_max(TimeGenerated, Upn, IsAccountEnabled, AccountDisplayName, AssignedRoles, GroupMembership) by AccountObjectId
    | extend ObjectId = tolower(AccountObjectId);
let GuestIds = toscalar(Guests | summarize make_set(ObjectId));
let Active = union
      (SigninLogs | where TimeGenerated > ago(Lookback) | where ResultType == "0" | where tolower(UserId) in (GuestIds) | project ObjectId = tolower(UserId), TimeGenerated),
      (AADNonInteractiveUserSignInLogs | where TimeGenerated > ago(Lookback) | where ResultType == "0" | where tolower(UserId) in (GuestIds) | project ObjectId = tolower(UserId), TimeGenerated)
    | summarize LastSeen = max(TimeGenerated) by ObjectId;
Guests
| join kind=leftouter Active on ObjectId
| extend DaysSilent = iff(isnull(LastSeen), 9999, datetime_diff("day", now(), LastSeen))
| where DaysSilent >= MinSilentDays
| extend HasRole = isnotempty(tostring(AssignedRoles)) and tostring(AssignedRoles) !in ("[]", "null", "")
| extend HomeDomain = coalesce(extract(@"(?i)_([^_]+)#ext#", 1, Upn), tostring(split(Upn, "@")[1]))
| project Upn, AccountDisplayName, AccountObjectId, HomeDomain, IsAccountEnabled, LastSeen, DaysSilent, HasRole, AssignedRoles, GroupMembership
| sort by HasRole desc, DaysSilent desc

// Hunting query, not an alert
let Lookback = 7d;
let FailWindow = 15m;
let IocIps = dynamic(["199.19.77.84"]);
let IocUserAgents = dynamic(["task177-f2267/1.0", "sait-tenant-deep/37346"]);
let SecretErrors = dynamic([7000215, 7000222]);
let Recent = EntraIdSpnSignInEvents
    | where Timestamp > ago(Lookback)
    | where IsManagedIdentity == false;
let IocHits = Recent
    | where IPAddress in (IocIps) or UserAgent in~ (IocUserAgents)
    | project Timestamp, ReportId, Signal = "Known operator IP or client string", ServicePrincipalName, ServicePrincipalId, IPAddress, UserAgent, Detail = strcat("ErrorCode ", ErrorCode);
let FailPairs = Recent
    | where ErrorCode in (SecretErrors)
    | distinct ServicePrincipalId, IPAddress;
let FailThenSuccess = Recent
    | where ErrorCode == 0 or ErrorCode in (SecretErrors)
    | join hint.strategy=broadcast kind=leftsemi FailPairs on ServicePrincipalId, IPAddress
    | summarize Failures = countif(ErrorCode != 0), Successes = countif(ErrorCode == 0), FirstFail = minif(Timestamp, ErrorCode != 0), LastSuccess = maxif(Timestamp, ErrorCode == 0), ReportId = take_anyif(ReportId, ErrorCode == 0), ServicePrincipalName = take_any(ServicePrincipalName), UserAgent = take_anyif(UserAgent, ErrorCode == 0) by ServicePrincipalId, IPAddress, Window = bin(Timestamp, FailWindow)
    | where Failures > 0 and Successes > 0 and LastSuccess > FirstFail
    | summarize Windows = count(), FirstSeen = min(FirstFail), Timestamp = max(LastSuccess), ReportId = take_any(ReportId), ServicePrincipalName = take_any(ServicePrincipalName), UserAgent = take_any(UserAgent) by ServicePrincipalId, IPAddress
    | project Timestamp, ReportId, Signal = "Invalid secret then successful sign-in from the same IP", ServicePrincipalName, ServicePrincipalId, IPAddress, UserAgent, Detail = strcat(Windows, " windows since ", format_datetime(FirstSeen, "yyyy-MM-dd HH:mm"));
let FirstActivity = EntraIdSpnSignInEvents
    | where Timestamp > ago(30d)
    | where ErrorCode == 0 and IsManagedIdentity == false
    | summarize FirstSuccess = min(Timestamp), Events = count(), IPs = make_set(IPAddress, 5), UserAgents = make_set(UserAgent, 3), Resources = make_set(ResourceDisplayName, 3) by ServicePrincipalId, ServicePrincipalName
    | where FirstSuccess > ago(Lookback)
    | project Timestamp = FirstSuccess, Signal = "App with no successful sign-in earlier in the 30 day window", ServicePrincipalName, ServicePrincipalId, IPAddress = strcat_array(IPs, ", "), UserAgent = strcat_array(UserAgents, ", "), Detail = strcat(Events, " sign-ins, resources: ", strcat_array(Resources, ", "));
union IocHits, FailThenSuccess, FirstActivity
| order by Timestamp desc

