// Hunting query, not an alert
// A success after failures on the same account needs urgent review. Thresholds are starting points.
let Lookback = 1d;
let MinFailures = 20;
let MinIps = 10;
union isfuzzy=true SigninLogs, AADNonInteractiveUserSignInLogs
| where TimeGenerated > ago(Lookback)
| where ClientAppUsed =~ "Authenticated SMTP"
| summarize Failures = countif(ResultType in ("50126", "50053")), Successes = countif(ResultType == "0"),
    FailedIps = dcountif(IPAddress, ResultType in ("50126", "50053")),
    SuccessIps = make_set_if(IPAddress, ResultType == "0", 5),
    FirstSeen = min(TimeGenerated), LastSeen = max(TimeGenerated)
    by UserPrincipalName, Day = bin(TimeGenerated, 1d)
| where Failures >= MinFailures and FailedIps >= MinIps
| extend SuccessAfterFailures = Successes > 0
| sort by SuccessAfterFailures desc, Failures desc

// Hunting query, not an alert
// Run in Defender portal advanced hunting with the Sentinel workspace connected.
let Lookback = 7d;
let Baseline = 30d;
let Window = 24h;
let BaselineIps = materialize(
    union isfuzzy=true SigninLogs, AADNonInteractiveUserSignInLogs
    | where TimeGenerated between (ago(Baseline + Lookback) .. ago(Lookback))
    | where ResultType == "0"
    | distinct User = tolower(UserPrincipalName), IPAddress, Country = tostring(LocationDetails.countryOrRegion));
let BaselineUsers = BaselineIps | distinct User;
let BaselineCountries = BaselineIps | distinct User, Country | extend Seen = true;
let NewIpSignIns = union isfuzzy=true SigninLogs, AADNonInteractiveUserSignInLogs
    | where TimeGenerated > ago(Lookback)
    | where ResultType == "0"
    | extend User = tolower(UserPrincipalName), Country = tostring(LocationDetails.countryOrRegion)
    | join kind=inner BaselineUsers on User
    | join kind=leftanti BaselineIps on User, IPAddress
    | join kind=leftouter BaselineCountries on User, Country
    | project SignInTime = TimeGenerated, User, IPAddress, Country,
        NewCountry = isnull(Seen), SignInType = iff(Type == "SigninLogs", "Interactive", "NonInteractive");
let Phish = EmailEvents
    | where Timestamp > ago(Lookback)
    | where ThreatTypes has "Phish" and DeliveryAction in ("Delivered", "Junked")
    | project PhishTime = Timestamp, User = tolower(RecipientEmailAddress), NetworkMessageId;
NewIpSignIns
| join kind=inner Phish on User
| where SignInTime between (PhishTime .. (PhishTime + Window))
| extend MinutesAfterPhish = datetime_diff('minute', SignInTime, PhishTime)
| summarize PhishEmails = dcount(NetworkMessageId), NewIpSignIns = count(), NewCountrySignIns = countif(NewCountry),
    FastestMinutes = min(MinutesAfterPhish), SignInTypes = make_set(SignInType),
    Ips = make_set(IPAddress, 5), Countries = make_set(Country, 5)
    by User
| sort by NewCountrySignIns desc, FastestMinutes asc

