| summarize Failures = countif(ErrorCode != 0), Lockouts = countif(ErrorCode == 50053), FailedAccounts = dcountif(AccountUpn, ErrorCode != 0), Successes = countif(ErrorCode == 0), SucceededAccounts = make_set_if(AccountUpn, ErrorCode == 0, 5), ScriptedAttempts = countif(UserAgent matches regex @"(?i)^(python-(requests|urllib)|curl)/"), UserAgents = make_set(UserAgent, 5), Countries = make_set(Country, 3), FirstSeen = min(Timestamp), LastSeen = max(Timestamp) by IPAddress, WindowStart = bin(Timestamp, Window)
| extend FailureRatio = round(todouble(Failures) / (Failures + Successes), 3)
| where (FailedAccounts >= MinAccounts and Failures >= MinFailures and FailureRatio >= MinFailureRatio) or (IPAddress in (IocIps) and Failures > 0)
| extend KnownIndicatorIp = IPAddress in (IocIps), ScriptedClient = ScriptedAttempts > 0, SuccessAfterFailures = Successes > 0
| order by KnownIndicatorIp desc, SuccessAfterFailures desc, Failures desc

// Hunting query, not an alert
let Lookback = 1d;
let Baseline = 14d;
let MinVaults = 3;
let MinReads = 10;
let SecretOps = dynamic(["SecretGet", "SecretList"]);
let History = CloudKeyVaultEvents
| where Timestamp between (ago(Baseline) .. ago(Lookback))
| where ActivityName in~ (SecretOps) and HttpStatusCode == 200
| summarize DailyVaults = dcount(VaultName) by AccountObjectId, Day = bin(Timestamp, 1d)
| summarize BaselineMaxVaults = max(DailyVaults) by AccountObjectId;
CloudKeyVaultEvents
| where Timestamp > ago(Lookback)
| where ActivityName in~ (SecretOps) and HttpStatusCode == 200
| summarize Vaults = dcount(VaultName), SecretReads = count(), VaultList = make_set(VaultName, 10), SourceIps = make_set(IPAddress, 5), UserAgents = make_set(UserAgentHeader, 3), FirstSeen = min(Timestamp), LastSeen = max(Timestamp) by AccountObjectId, AccountApplicationId, AccountUpn, AccountType
| join kind=leftouter History on AccountObjectId
| extend BaselineMaxVaults = coalesce(BaselineMaxVaults, 0)
| where Vaults >= MinVaults and SecretReads >= MinReads and Vaults > BaselineMaxVaults
| project Timestamp = LastSeen, FirstSeen, AccountType, AccountObjectId, AccountApplicationId, AccountUpn, Vaults, BaselineMaxVaults, SecretReads, VaultList, SourceIps, UserAgents
| order by Vaults desc, SecretReads desc

// Hunting query, not an alert
let Hunt = (N: (Timestamp: datetime, DeviceName: string, RemoteUrl: string, InitiatingProcessFileName: string), P: (Timestamp: datetime, DeviceName: string, FileName: string, ProcessCommandLine: string), F: (Timestamp: datetime, DeviceName: string, ActionType: string, FileName: string, FolderPath: string)) {
  let Net = N
    | where Timestamp > ago(30d)
    | where RemoteUrl has "webhook.site"
    | project Timestamp, DeviceName, Signal = "Connection to webhook.site", Detail = strcat(InitiatingProcessFileName, " -> ", RemoteUrl);
  let Cmd = P
    | where Timestamp > ago(30d)
    | where FileName in~ ("curl.exe", "powershell.exe", "pwsh.exe", "cmd.exe", "wget.exe")
    | where ProcessCommandLine has "webhook.site"
    | project Timestamp, DeviceName, Signal = "Command line posting to webhook.site", Detail = strcat(FileName, " ", ProcessCommandLine);
  let Acct = P
    | where Timestamp > ago(30d)
    | where ProcessCommandLine contains "ArtexProbe"
    | project Timestamp, DeviceName, Signal = "ArtexProbe account name in command line", Detail = strcat(FileName, " ", ProcessCommandLine);
  let Files = F
    | where Timestamp > ago(30d)
    | where ActionType in ("FileCreated", "FileModified", "FileRenamed")
    | where FileName startswith "artex-probe-" or FileName in~ ("cl1217.jsp", "f1219a.jsp", "z1219.jsp")
    | project Timestamp, DeviceName, Signal = "ARTEX probe file or known web shell name", Detail = strcat(FolderPath, "\\", FileName);
  union Net, Cmd, Acct, Files
  | summarize Events = count(), FirstSeen = min(Timestamp), LastSeen = max(Timestamp), Examples = make_set(Detail, 5) by DeviceName, Signal
  | project Timestamp = LastSeen, DeviceName, Signal, Events, FirstSeen, Examples
  | order by Timestamp desc
};
Hunt(DeviceNetworkEvents, DeviceProcessEvents, DeviceFileEvents)
